parameters.pythonCode:
import base64
import json
# 1. Create a single dictionary with all items (Your existing logic)
combined_data = {
    index: {'first_wave':item.json.to_py()} 
    for index, item in enumerate(_input.all())
}

# 2. Convert the dictionary to a JSON string
json_string = json.dumps(combined_data, indent=2, ensure_ascii=False)

# 2. Then encode to binary as usual
b64_string = base64.b64encode(json_string.encode('utf-8')).decode('utf-8')
# 4. Return the item with the "binary" structure
return [{
    "json": {
        "data": json_string  # Keeps the data visible in the UI (optional)
    },
    "binary": {
        "data": {  # <--- The Write to Disk node looks for this key 'data'
            "data": b64_string,
            "mimeType": "application/json",
            "fileName": "combined_output.json"
        }
    }
}]
